  [1248688] = { "栄養のある食事でWell Fedになり、移動速度が上昇します。", { "Westfallにいる間、移動速度が$N1%上昇します。敵を倒して得る経験値が$N2%増加します。", "Westfallにいる間、移動速度が$N1%上昇します。", shape = { "2/0", "1/0" } }, 0xb9353e68, 0xa9c2d337, "uu" },
