  [1248757] = { "Melee Weaponに永続的なエンチャントを施し、呪文を唱えたときに一定の確率でInsightを付与するようにします。Insightは$D1の間、精神を$N1%増加させます。", nil, 0x375e31e1, nil, "um" },
